using System.Collections.Generic;

namespace FF14Accessibility.Services;

/// <summary>
/// Russische Monsternamen -> Zeilen-Ids im BNpcName-Blatt.
///
/// Warum es das braucht: im Kampf liest der Mod den Namen vom Objekt, und den
/// hat das Rusik uebersetzt - im Jagdjournal liest er das Blatt, und Blaetter
/// liefern in dieser Installation ENGLISCH. Die Spielerin hoerte deshalb
/// "Хворемит" im Kampf und "Ixali deftalon" im Journal (Meldung 2026-09-14,
/// msg 11139). Dieselbe Ursache wie bei Attributen, Klassen, Gesellschaften
/// und Ortsnamen - und dieselbe Loesung.
///
/// Quelle ist die Uebersetzungsdatei des Rusik selbst (exd/BNpcName/ru.xlf,
/// abgerufen am 2026-09-14): genau die Namen, die im russischen Spiel auf der
/// Namensplakette stehen - also auch die, gegen die
/// <see cref="HuntingLogService.FindNearestLive"/> vergleicht.
///
/// Nicht enthalten: Zeilen ohne kyrillische Uebersetzung (das Rusik deckt
/// nicht jeden Namen ab). Sie enden in null - der Mod sagt dann den
/// Blattnamen (englisch) wie bisher, nie etwas Falsches.
/// 6365 Namen; generiert, nicht von Hand pflegen.
/// </summary>
internal static class RussianMonsterNames
{
    /// <summary>Einzahl des Monsternamens, oder null, wenn die Zeile nicht
    /// uebersetzt ist.</summary>
    public static string? MonsterName(uint rowId) =>
        Names.TryGetValue(rowId, out var name) ? name : null;

